17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	
23	import org.slf4j.Logger;
24	import org.slf4j.LoggerFactory;
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.audit.OwnerAuditEvents;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.mapper.PetMapper;
31	import org.springframework.samples.petclinic.mapper.VisitMapper;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
43	import org.springframework.samples.petclinic.rest.validation.EmailDomainValidator;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private static final Logger auditLogger = LoggerFactory.getLogger("AUDIT");
63	
64	    private static final Logger notifyLogger = LoggerFactory.getLogger("NOTIFY");
65	
66	    /** The per-city soft capacity: at or above this owner count a city is over its soft capacity. */
67	    private static final int SOFT_CAPACITY = 40;
68	
69	    /** The per-city hard limit: a create is rejected once a city already holds this many owners. */
70	    private static final int HARD_CAPACITY = 50;
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    private final OwnerAuditEvents ownerAuditEvents;
81	
82	    public OwnerRestControllerV1(ClinicService clinicService,
83	                                 OwnerMapper ownerMapper,
84	                                 PetMapper petMapper,
85	                                 VisitMapper visitMapper,
86	                                 OwnerAuditEvents ownerAuditEvents) {
87	        this.clinicService = clinicService;
88	        this.ownerMapper = ownerMapper;
89	        this.petMapper = petMapper;
90	        this.visitMapper = visitMapper;
91	        this.ownerAuditEvents = ownerAuditEvents;
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
97	        Collection<Owner> owners;
98	        if (lastName != null) {
99	            owners = this.clinicService.findOwnerByLastName(lastName);
100	        } else {
101	            owners = this.clinicService.findAllOwners();
102	        }
103	        if (owners.isEmpty()) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
112	        Owner owner = this.clinicService.findOwnerById(ownerId);
113	        if (owner == null) {
114	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
115	        }
116	        return new ResponseEntity<>(toOwnerDtoWithDerived(owner), HttpStatus.OK);
117	    }
118	
119	    /**
120	     * Builds the read representation of a persisted owner, populating the derived fields
121	     * ({@code householdSize}, {@code bulkSignupWarning}, {@code capacityWarning}) that are not
122	     * stored on the entity.
123	     */
124	    private OwnerDto toOwnerDtoWithDerived(Owner owner) {
125	        owner.setHouseholdSize(this.clinicService.countOwnersByHouseholdId(owner.getHouseholdId()));
126	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
127	        ownerDto.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
128	        ownerDto.setCapacityWarning(isApproachingCapacity(owner.getCity()));
129	        ownerDto.setRiskFlag(isRisk(owner));
130	        return ownerDto;
131	    }
132	
133	    /**
134	     * Whether the owner should be flagged for review via the read-only {@code riskFlag} field: true
135	     * when any of the following hold, otherwise false. The owner is a possible duplicate
136	     * ({@link Owner#getPossibleDuplicate()}); its email domain is disposable-adjacent
137	     * ({@link EmailDomainValidator#isDisposableAdjacent(String)}); or its city is over its soft
138	     * capacity (see {@link #isOverSoftCapacity(String)}).
139	     */
140	    private boolean isRisk(Owner owner) {
141	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
142	            || EmailDomainValidator.isDisposableAdjacent(owner.getEmail())
143	            || isOverSoftCapacity(owner.getCity());
144	    }
145	
146	    /**
147	     * Whether {@code city} is over its soft capacity: it already holds {@link #SOFT_CAPACITY} or
148	     * more owners. The soft capacity sits below the per-city hard limit enforced at create time
149	     * (see {@link #addOwner}), so this stays true from the soft capacity right up to the full city.
150	     */
151	    private boolean isOverSoftCapacity(String city) {
152	        return this.clinicService.countOwnersByCity(city) >= SOFT_CAPACITY;
153	    }
154	
155	    /**
156	     * Whether more than 80 owners have already been created on {@code registrationDate},
157	     * signalling a bulk-signup surge for the read-only {@code bulkSignupWarning} field.
158	     */
159	    private boolean isBulkSignup(LocalDate registrationDate) {
160	        return this.clinicService.countOwnersByRegistrationDate(registrationDate) > 80;
161	    }
162	
163	    /**
164	     * Whether {@code city} already holds from the soft capacity up to one below the hard limit
165	     * (40 to 49 inclusive), signalling that it is approaching the per-city capacity limit of 50,
166	     * for the read-only {@code capacityWarning} field. The hard rejection at 50 (see
167	     * {@link #addOwner}) is unaffected.
168	     */
169	    private boolean isApproachingCapacity(String city) {
170	        int count = this.clinicService.countOwnersByCity(city);
171	        return count >= SOFT_CAPACITY && count < HARD_CAPACITY;
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Override
176	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
177	        // Idempotent replay: a repeat with an already-seen key returns the originally created
178	        // owner with 200 rather than creating (and possibly rejecting as) a duplicate.
179	        Integer existingId = this.clinicService.findOwnerIdByIdempotencyKey(idempotencyKey);
180	        if (existingId != null) {
181	            Owner existing = this.clinicService.findOwnerById(existingId);
182	            if (existing != null) {
183	                return new ResponseEntity<>(toOwnerDtoWithDerived(existing), HttpStatus.OK);
184	            }
185	        }
186	        HttpHeaders headers = new HttpHeaders();
187	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
188	        LocalDate registrationDate = owner.resolveRegistrationDate();
189	        if (this.clinicService.countOwnersByRegistrationDate(registrationDate) >= 100) {
190	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
191	        }
192	        if (this.clinicService.countOwnersByCity(owner.getCity()) >= HARD_CAPACITY) {
193	            return new ResponseEntity<>(HttpStatus.CONFLICT);
194	        }
