package org.springframework.samples.petclinic.acceptance;

import org.junit.jupiter.api.Test;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import tools.jackson.databind.node.ObjectNode;

class TmpProblemTest extends AcceptanceBase {

	@Test
	void conflictIsProblemJson() throws Exception {
		ObjectNode base = structuredOwner();
		createOwnerOk(base.deepCopy());
		// exact same identity -> 409
		createOwner(base.deepCopy()).andExpect(status().isConflict())
				.andExpect(content().contentTypeCompatibleWith("application/problem+json"))
				.andExpect(jsonPath("$.status").value(409))
				.andExpect(jsonPath("$.type").exists())
				.andExpect(jsonPath("$.title").exists())
				.andExpect(jsonPath("$.detail").exists());
	}

	@Test
	void rateLimitIsProblemJson() throws Exception {
		fillCity("RateCity", 0);
		createMany(100);
		createOwner(ownerNode()).andExpect(status().isTooManyRequests())
				.andExpect(content().contentTypeCompatibleWith("application/problem+json"))
				.andExpect(jsonPath("$.status").value(429))
				.andExpect(jsonPath("$.type").exists())
				.andExpect(jsonPath("$.title").exists())
				.andExpect(jsonPath("$.detail").exists());
	}
}

